// A scanner for the tree's own C++ (Source/, generated by the decompiler pipeline): the function
// definitions and declarations at namespace scope of one file, with the namespace they sit in, the
// preprocessor conditions around them, their specifiers and their parameter lists, and the
// typedefs, enums and records the file declares. It is not a C++ parser; it relies on the shape
// the generator writes (one definition head per line, a namespace block around them) and reports
// what it cannot read instead of guessing.

export type Param = { text: string; type: string; name: string };

export type FunctionHead = {
    name: string;            // unqualified ("GetSkillLevel"; "TSList<X>::Ptr" for a qualified head)
    namespace: string[];     // the enclosing namespace blocks, outermost first
    ret: string;             // the return type as written, specifiers removed
    conv: "" | "__fastcall" | "__stdcall" | "__thiscall" | "__cdecl";
    params: Param[];
    variadic: boolean;
    isStatic: boolean;
    isInline: boolean;
    forceInline: boolean;    // always_inline: every call is inlined, even at -O0
    isTemplate: boolean;
    qualified: boolean;      // the name carries a scope (a member defined out of its class)
    definition: boolean;     // a body follows (else a declaration)
    conditions: string[];    // the #if lines it sits under, outermost first
    line: number;
};

export type ScanResult = {
    functions: FunctionHead[];
    typedefs: Map<string, string>;  // name -> the type it names
    enums: Set<string>;
    records: Set<string>;           // struct/class/union names defined or declared
};

// The text of a file with comments and string/char contents blanked (same length, newlines kept),
// so offsets and line numbers stay those of the file.
export function blank(src: string): string {
    const out: string[] = [];
    let i = 0;
    const n = src.length;
    while (i < n) {
        const c = src[i];
        const d = src[i + 1];
        if (c === "/" && d === "/") {
            while (i < n && src[i] !== "\n") {
                out.push(" ");
                i++;
            }
            continue;
        }
        if (c === "/" && d === "*") {
            out.push("  ");
            i += 2;
            while (i < n && !(src[i] === "*" && src[i + 1] === "/")) {
                out.push(src[i] === "\n" ? "\n" : " ");
                i++;
            }
            if (i < n) {
                out.push("  ");
                i += 2;
            }
            continue;
        }
        if (c === '"' || c === "'") {
            // A raw string (R"x(...)x") is not used by the tree's generator; plain escapes only.
            out.push(c);
            i++;
            while (i < n && src[i] !== c) {
                if (src[i] === "\\") {
                    out.push("  ");
                    i += 2;
                    continue;
                }
                out.push(src[i] === "\n" ? "\n" : " ");
                i++;
            }
            if (i < n) {
                out.push(c);
                i++;
            }
            continue;
        }
        out.push(c);
        i++;
    }
    return out.join("");
}

type Scope = { kind: "namespace" | "linkage" | "other"; name?: string };

const CONVS = ["__fastcall", "__stdcall", "__thiscall", "__cdecl"] as const;

function splitTopLevel(text: string, sep: string): string[] {
    const parts: string[] = [];
    let depth = 0;
    let cur = "";
    for (const ch of text) {
        if (ch === "(" || ch === "<" || ch === "[" || ch === "{") depth++;
        else if (ch === ")" || ch === ">" || ch === "]" || ch === "}") depth--;
        if (ch === sep && depth === 0) {
            parts.push(cur);
            cur = "";
        } else cur += ch;
    }
    if (cur.trim().length || parts.length) parts.push(cur);
    return parts;
}

// "struct D2UnitStrc * pUnit" -> type "struct D2UnitStrc *", name "pUnit"; "int a[4]" -> "int *";
// "void (*pfn)(int)" -> "void (*)(int)". An unnamed parameter keeps its whole text as the type.
export function splitParam(text: string): Param {
    let t = text.replace(/\s+/g, " ").trim();
    const def = splitTopLevel(t, "=");
    if (def.length > 1) t = def[0].trim();
    const fp = /^(.*)\(\s*([*&])\s*(\w*)\s*\)\s*(\(.*\))\s*$/.exec(t);
    if (fp) return { text: t, type: `${fp[1].trim()} (${fp[2]})${fp[4]}`, name: fp[3] };
    const arr = /^(.*?)\s*(\w+)\s*((?:\[[^\]]*\])+)$/.exec(t);
    if (arr) return { text: t, type: `${arr[1].trim()} *`, name: arr[2] };
    const m = /^(.*?[\s*&])(\w+)$/.exec(t);
    if (m && !/^(const|volatile|unsigned|signed|int|char|short|long|float|double|bool|void|struct|enum|union|class)$/.test(m[2])) {
        const type = m[1].trim();
        // "unsigned int" / "struct X" alone: the last word is part of the type.
        if (type.length && !/^(struct|enum|union|class|unsigned|signed|const|volatile)$/.test(type)) return { text: t, type, name: m[2] };
    }
    return { text: t, type: t, name: "" };
}

// Parse a head "specifiers ret conv name(params) trailing" into a FunctionHead, or null when it is
// not a function head.
export function parseHead(head: string): Omit<FunctionHead, "namespace" | "conditions" | "line" | "definition"> | null {
    let h = head.replace(/\s+/g, " ").trim();
    if (!h.endsWith(")")) {
        // trailing qualifiers after the parameter list
        h = h.replace(/\)\s*(const|noexcept|throw\s*\(\s*\)|override|final|__attribute__\s*\(\(.*?\)\))*\s*$/, ")");
        if (!h.endsWith(")")) return null;
    }
    // the parameter list: the last top-level parenthesised group
    let depth = 0;
    let open = -1;
    for (let i = h.length - 1; i >= 0; i--) {
        if (h[i] === ")") depth++;
        else if (h[i] === "(") {
            depth--;
            if (depth === 0) {
                open = i;
                break;
            }
        }
    }
    if (open < 0) return null;
    const paramText = h.slice(open + 1, -1).trim();
    let before = h.slice(0, open).trimEnd();
    // the name, possibly qualified with template arguments: walk back over identifier chars, ::, <...>
    let j = before.length;
    let angle = 0;
    while (j > 0) {
        const ch = before[j - 1];
        if (ch === ">") {
            angle++;
            j--;
            continue;
        }
        if (ch === "<") {
            angle--;
            j--;
            continue;
        }
        if (angle > 0) {
            j--;
            continue;
        }
        if (/[\w:~]/.test(ch)) {
            j--;
            continue;
        }
        break;
    }
    const name = before.slice(j).trim();
    before = before.slice(0, j).trim();
    if (!name || !/^[A-Za-z_~]/.test(name) || /^operator\b/.test(name)) return null;
    if (/^(if|while|for|switch|return|sizeof|decltype|catch|defined)$/.test(name)) return null;
    const words = before;
    if (!words.length) return null;  // a call or a constructor-like statement, no return type
    if (/[=]/.test(words) || /^(typedef|using|return|delete|new|goto)\b/.test(words)) return null;
    let specs = words;
    const isTemplate = /\btemplate\s*</.test(specs);
    specs = specs.replace(/\btemplate\s*<[^>]*>/g, " ");
    const forceInline = /\b(D2_FORCEINLINE|D2_SEED_ROLL_INLINE|__forceinline)\b|always_inline/.test(specs);
    const isStatic = /\bstatic\b/.test(specs);
    const isInline = /\binline\b/.test(specs) || forceInline;
    let conv: FunctionHead["conv"] = "";
    for (const c of CONVS) if (new RegExp(`\\b${c}\\b`).test(specs)) conv = c;
    specs = specs
        .replace(/__attribute__\s*\(\((?:[^()]|\([^()]*\))*\)\)/g, " ")
        .replace(/\[\[[^\]]*\]\]/g, " ")
        .replace(/__declspec\s*\([^)]*\)/g, " ")
        .replace(/\b(static|inline|extern|virtual|constexpr|explicit|friend|D2_FORCEINLINE|D2_SEED_ROLL_INLINE|__forceinline|D2_NOINLINE|__inline|__cdecl|__stdcall|__fastcall|__thiscall|WINAPI|CALLBACK|APIENTRY|STDCALL)\b/g, " ")
        .replace(/\s+/g, " ")
        .trim();
    if (/\bWINAPI\b|\bCALLBACK\b|\bAPIENTRY\b/.test(words)) conv = "__stdcall";
    if (!specs.length) return null;
    if (/^(struct|class|union|enum|namespace)\s+\w+$/.test(specs) && !/\*/.test(specs)) {
        // "struct X" alone is a valid return type; keep it.
    }
    let params: Param[] = [];
    let variadic = false;
    if (paramText.length && paramText !== "void") {
        for (const p of splitTopLevel(paramText, ",")) {
            const t = p.trim();
            if (t === "...") {
                variadic = true;
                continue;
            }
            params.push(splitParam(t));
        }
    }
    return { name, ret: specs, conv, params, variadic, isStatic, isInline, forceInline, isTemplate, qualified: name.includes("::") };
}

export function scan(src: string): ScanResult {
    const text = blank(src);
    const functions: FunctionHead[] = [];
    const typedefs = new Map<string, string>();
    const enums = new Set<string>();
    const records = new Set<string>();
    const scopes: Scope[] = [];
    const conds: string[] = [];
    let buf = "";
    let bufLine = 1;
    let line = 1;
    let i = 0;
    const n = text.length;
    let atLineStart = true;
    const atNamespaceScope = () => scopes.every((s) => s.kind !== "other");
    const nsPath = () => scopes.filter((s) => s.kind === "namespace" && s.name).flatMap((s) => s.name!.split("::"));
    const note = (stmt: string) => {
        const s = stmt.replace(/\s+/g, " ").trim();
        let m = /^typedef (.+?)\s*\b(\w+)\s*$/.exec(s);
        if (m && !/\(/.test(s)) typedefs.set(m[2], m[1].trim());
        m = /^typedef .*\(\s*(?:__\w+\s*)?\*\s*(\w+)\s*\)\s*\(.*\)$/.exec(s);
        if (m) typedefs.set(m[1], "(*fn)");
        m = /^using (\w+) = (.+)$/.exec(s);
        if (m) typedefs.set(m[1], m[2].trim());
        m = /^(?:typedef )?(struct|class|union) (\w+)$/.exec(s);
        if (m) records.add(m[2]);
        m = /^enum (?:class |struct )?(\w+)(?:\s*:.*)?$/.exec(s);
        if (m) enums.add(m[1]);
    };
    while (i < n) {
        const c = text[i];
        if (atLineStart) {
            // skip whitespace to see whether this is a preprocessor line
            let k = i;
            while (k < n && (text[k] === " " || text[k] === "\t")) k++;
            if (text[k] === "#") {
                let end = k;
                let directive = "";
                while (end < n) {
                    if (text[end] === "\n" && text[end - 1] !== "\\") break;
                    if (text[end] === "\n") line++;
                    end++;
                }
                directive = src.slice(k, end).replace(/\\\n/g, " ").replace(/\/\/.*$/, "").replace(/\/\*.*?\*\//g, "").trim();
                const d = /^#\s*(\w+)\s*(.*)$/.exec(directive);
                if (d) {
                    const [, kw, rest] = d;
                    if (kw === "if" || kw === "ifdef" || kw === "ifndef") conds.push(kw === "if" ? `#if ${rest}` : `#${kw} ${rest}`);
                    else if (kw === "elif") {
                        const top = conds.pop() ?? "#if 1";
                        conds.push(`${negate(top)} && (${rest})`);
                    } else if (kw === "else") {
                        const top = conds.pop() ?? "#if 1";
                        conds.push(negate(top));
                    } else if (kw === "endif") conds.pop();
                }
                i = end;
                continue;
            }
            atLineStart = false;
        }
        if (c === "\n") {
            line++;
            atLineStart = true;
            buf += c;
            i++;
            continue;
        }
        if (!atNamespaceScope()) {
            // inside a body or a record: only braces matter
            if (c === "{") scopes.push({ kind: "other" });
            else if (c === "}") scopes.pop();
            i++;
            continue;
        }
        if (c === "{") {
            const head = buf.trim().replace(/^(D2_PACKED_END\s*)+/, "").trim();
            const ns = /(?:^|\s)(?:inline\s+)?namespace\s*([\w:]*)\s*$/.exec(head);
            if (ns) {
                scopes.push({ kind: "namespace", name: ns[1] || undefined });
            } else if (/^extern\s*"\s*C\s*"\s*$/.test(head)) {
                scopes.push({ kind: "linkage" });
            } else {
                const parsed = /\)\s*(const|noexcept|override|final|throw\s*\(\s*\))*\s*$/.test(head) && !/^(struct|class|union|enum)\b/.test(head)
                    ? parseHead(head) : null;
                if (parsed) {
                    functions.push({ ...parsed, namespace: nsPath(), conditions: [...conds], line: bufLine, definition: true });
                } else {
                    const rec = /^(?:typedef\s+)?(?:D2_PACKED_BEGIN\s+)?(struct|class|union)\s+(?:__attribute__\s*\(\([^)]*\)\)\s*)?(\w+)/.exec(head);
                    if (rec) records.add(rec[2]);
                    const en = /^(?:typedef\s+)?enum\s+(?:class\s+|struct\s+)?(\w+)/.exec(head);
                    if (en) enums.add(en[1]);
                }
                scopes.push({ kind: "other" });
            }
            buf = "";
            i++;
            bufLine = line;
            continue;
        }
        if (c === "}") {
            scopes.pop();
            buf = "";
            i++;
            bufLine = line;
            continue;
        }
        if (c === ";") {
            const stmt = buf.trim().replace(/^(D2_PACKED_END\s*)+/, "").trim();
            note(stmt);
            if (/\)\s*(const|noexcept|override|final|throw\s*\(\s*\)|__attribute__\s*\(\(.*\)\))*\s*$/.test(stmt) && !/^(typedef|using|struct|class|enum|union)\b/.test(stmt)) {
                const parsed = parseHead(stmt);
                if (parsed) functions.push({ ...parsed, namespace: nsPath(), conditions: [...conds], line: bufLine, definition: false });
            }
            // "} name;" after a typedef struct: the record's typedef name
            buf = "";
            i++;
            bufLine = line;
            continue;
        }
        if (!buf.trim().length) bufLine = line;
        buf += c;
        i++;
    }
    return { functions, typedefs, enums, records };
}

function negate(cond: string): string {
    if (cond.startsWith("#ifdef ")) return `#if !defined(${cond.slice(7).trim()})`;
    if (cond.startsWith("#ifndef ")) return `#if defined(${cond.slice(8).trim()})`;
    return `#if !(${cond.replace(/^#if\s*/, "")})`;
}
